	local tooltipData = C_TooltipInfo.GetWorldCursor();
	if not parent then
		parent = UIParent;
	end

	if anchorType == Enum.WorldCursorAnchorType.Default then
		GameTooltip_SetDefaultAnchor(self, parent);
